paginas.texto:
Muchas tareas se repiten en casi todas las rutas: comprobar quién llama, registrar la petición, leer el cuerpo JSON, comprimir la respuesta. En lugar de copiarlas en cada controlador, se escriben como [[middlewares|middleware]].

Un middleware es una función que se ejecuta en la **cadena** (pipeline) por la que pasa cada petición. Puede:

• leer o **modificar** la petición (por ejemplo, añadir `req.usuario`);
• **terminar** la respuesta (por ejemplo, devolver 401);
• **pasar** al siguiente eslabón llamando a [[next()|funcion_next]].

paginas.codigo:
function registrar(req, res, next) {
  const inicio = Date.now();
  res.on('finish', () => {
    console.log(`${req.method} ${req.url} ${res.statusCode} ${Date.now() - inicio} ms`);
  });
  next();
}

app.use(registrar);

app.get('/api/productos', (req, res) => {
  res.json([{ id: 1, nombre: 'Poncho' }]);
});

app.use(express.json());   // global: lee cuerpos JSON
app.use(registrar);         // global: logs

// Solo en rutas de administración
app.delete('/api/productos/:id', autenticar, soloAdmin, borrarProducto);

// Para un grupo de rutas
app.use('/api/admin', autenticar, soloAdmin);

function cabecerasSeguridad(req, res, next) {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'no-store');
  next();
}

app.use(compression());  // comprime la respuesta al enviarla
app.use('/api/cuenta', cabecerasSeguridad);

app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status ?? 500).json({ error: 'Algo salió mal' });
});

function autenticar(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  const usuario = verificarToken(token);
  if (!usuario) return res.status(401).json({ error: 'No autenticado' });
  req.usuario = usuario;
  next();
}

function soloAdmin(req, res, next) {
  if (req.usuario.rol !== 'admin') return res.status(403).json({ error: 'Sin permiso' });
  next();
}
